package vn.rtr.aeris.crew02;
import java.io.*;import java.util.*;
/** Pure identity/presence/session guard. Native gateway serializes it under transport, no inner locks. */
public final class CrewSession02{
 public static final long PRESENCE_MS=3000;public final String serverBoot=UUID.randomUUID().toString();private long last=-1;private int created=0;private long epoch=0;private String realm="",aircraft="";private final Map<String,Session>sessions=new LinkedHashMap<>();
 public static final class Session{public final String id=UUID.randomUUID().toString(),challenge=UUID.randomUUID().toString(),principal,key,clientBoot,clientNonce;public final boolean local;public final long epoch,helloAt;public String generation="",sid="";public long seq=0,seen;public boolean joined=false,alive=true;public final Set<String>scopes;Session(String p,String k,String b,String nonce,boolean local,long e,long n,Set<String>s){principal=p;key=k;clientBoot=b;clientNonce=nonce;this.local=local;epoch=e;helloAt=n;seen=n;scopes=new HashSet<>(s);}}
 public void configure(long e,String r,String a,long now)throws IOException{time(now);for(Session s:sessions.values())s.alive=false;epoch=e;realm=r;aircraft=a;}
 private void time(long now)throws IOException{if(now<0||now<last){for(Session s:sessions.values())s.alive=false;throw new IOException("CREW_CLOCK_REGRESSION");}last=now;}
 public Session hello(String principal,String key,String clientBoot,String nonce,boolean local,Set<String>scopes,long now)throws IOException{time(now);if(epoch<1||created>=32||!clientBoot.matches("[a-zA-Z0-9_-]{1,64}")||!nonce.matches("[a-zA-Z0-9_-]{16,64}"))throw new IOException("CREW_HELLO_CONTEXT_OR_QUOTA");for(Session s:sessions.values())if(s.alive&&s.principal.equals(principal))throw new IOException("CREW_PRINCIPAL_ALREADY_CONNECTED");Session s=new Session(principal,key,clientBoot,nonce,local,epoch,now,scopes);sessions.put(s.id,s);created++;return s;}
 public void checkJoin(Session s,Map<String,Object>q,String generation,long now)throws IOException{time(now);current(s,now,false);StrictJson02.exact(q,"kind","serverBoot","clientBoot","clientNonce","challenge","channelId","realm","aircraft","trustEpoch","generation");if(!"JOIN".equals(q.get("kind"))||!serverBoot.equals(q.get("serverBoot"))||!s.clientBoot.equals(q.get("clientBoot"))||!s.clientNonce.equals(q.get("clientNonce"))||!s.challenge.equals(q.get("challenge"))||!s.id.equals(q.get("channelId"))||!realm.equals(q.get("realm"))||!aircraft.equals(q.get("aircraft"))||epoch!=StrictJson02.integer(q,"trustEpoch")||generation.isEmpty()||!generation.equals(q.get("generation"))||s.joined||now-s.helloAt>30000)throw new IOException("CREW_JOIN_BINDING");}
 public void join(Session s,Map<String,Object>q,String generation,String coreSid,long now)throws IOException{checkJoin(s,q,generation,now);s.generation=generation;s.sid=coreSid;s.joined=true;s.seen=now;}
 public boolean live02(Session s,long now)throws IOException{time(now);return s!=null&&sessions.get(s.id)==s&&s.alive&&s.joined&&s.epoch==epoch&&now-s.seen<=PRESENCE_MS;}
 public void current(Session s,long now,boolean joined)throws IOException{time(now);if(s==null||sessions.get(s.id)!=s||!s.alive||s.epoch!=epoch||(s.joined?now-s.seen>PRESENCE_MS:now-s.helloAt>30000)||joined&&!s.joined)throw new IOException("CREW_FRESH_AUTH_SESSION_REQUIRED");}
 public void envelope(Session s,Map<String,Object>q,String generation,long now)throws IOException{current(s,now,true);if(!serverBoot.equals(q.get("serverBoot"))||!s.clientBoot.equals(q.get("clientBoot"))||!s.id.equals(q.get("session"))||s.epoch!=StrictJson02.integer(q,"trustEpoch")||!s.generation.equals(generation)||!generation.equals(q.get("generation")))throw new IOException("CREW_SESSION_GENERATION_BINDING");long seq=StrictJson02.integer(q,"seq");if(seq!=s.seq+1||seq>10000)throw new IOException("CREW_SEQUENCE_FENCE");s.seq=seq;s.seen=now;}
 public void scope(Session s,String scope,long now)throws IOException{current(s,now,true);if(!s.scopes.contains(scope)||scope.equals("aircraft")&&!s.principal.equals("pilot-a"))throw new IOException("CREW_SCOPE_ROLE_DENIED");}
 public List<Session>expired(long now)throws IOException{time(now);List<Session>out=new ArrayList<>();for(Session s:sessions.values())if(s.alive&&(s.joined?now-s.seen>PRESENCE_MS:now-s.helloAt>30000)){s.alive=false;out.add(s);}return out;}
 public void lose(Session s){if(s!=null)s.alive=false;}
 public Session principal(String p){for(Session s:sessions.values())if(s.alive&&s.joined&&s.principal.equals(p))return s;return null;}
 public Collection<Session>all(){return Collections.unmodifiableCollection(sessions.values());}
 public long epoch(){return epoch;}public String realm(){return realm;}public String aircraft(){return aircraft;}
 public Map<String,Object>challenge(Session s){return Data97.m("kind","CHALLENGE","serverBoot",serverBoot,"clientBoot",s.clientBoot,"clientNonce",s.clientNonce,"challenge",s.challenge,"channelId",s.id,"realm",realm,"aircraft",aircraft,"trustEpoch",epoch,"principal",s.principal,"keyFingerprint",s.key,"authentication",s.local?"NATIVE_APP_CONTEXT":"MTLS_TEST_CERTIFICATE","authorityRestorable",false);}
}
